import { defineConfig } from 'vitest/config'

export default defineConfig({
	test: {
		environment: 'jsdom',
		coverage: {
			provider: 'v8',
			reporter: [
				[
					'json',
					{
						file: `../coverage.json`,
					},
				],
			],
			enabled: true,
		},
	},
})

import nextnodeEslint from '@nextnode/eslint-plugin/base'

export default [
	...nextnodeEslint,
	{
		ignores: ['dist/**', 'node_modules/**', '.astro/**', '**/.astro/**'],
	},
	{
		files: ['**/*.ts', '**/*.tsx'],
		languageOptions: {
			parserOptions: {
				project: './tsconfig.json',
			},
		},
	},
	{
		files: ['astro.config.mjs'],
		languageOptions: {
			globals: {
				process: 'readonly',
				console: 'readonly',
			},
		},
	},
]
